package com.csust.eyediagnosis.workflow.persistence.repository;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.csust.eyediagnosis.workflow.persistence.entity.InferenceEnvelopeEntity; import com.csust.eyediagnosis.workflow.persistence.mapper.InferenceEnvelopeMapper; import org.springframework.stereotype.Repository; import java.util.Optional;
@Repository public class MybatisInferenceEnvelopeRepository implements InferenceEnvelopeRepository { private final InferenceEnvelopeMapper mapper; public MybatisInferenceEnvelopeRepository(InferenceEnvelopeMapper mapper){this.mapper=mapper;} public int insert(InferenceEnvelopeEntity e){return mapper.insert(e);} public Optional<InferenceEnvelopeEntity> findByWorkflowIdAndEpoch(String id,long epoch){return Optional.ofNullable(mapper.selectOne(new LambdaQueryWrapper<InferenceEnvelopeEntity>().eq(InferenceEnvelopeEntity::getWorkflowId,id).eq(InferenceEnvelopeEntity::getInferenceEpoch,epoch)));} }
